mapper.select:
SELECT t_allocating_sprinkler.*, t_sprinkler.* FROM t_allocating_sprinkler LEFT JOIN t_sprinkler ON t_allocating_sprinkler.sprinkler_id = t_sprinkler.sprinkler_id
t_allocating_sprinkler.deleted_flag = #{queryForm.deletedFlag}
AND INSTR(t_sprinkler.sprinkler_model,#{queryForm.sprinklerModel})
AND INSTR(t_sprinkler.sprinkler_serial,#{queryForm.sprinklerSerial})
AND DATE_FORMAT(t_sprinkler.allocate_date, '%Y-%m-%d') >= #{queryForm.allocateDateStartTime}
AND DATE_FORMAT(t_sprinkler.allocate_date, '%Y-%m-%d') <= #{queryForm.allocateDateEndTime}
AND INSTR(t_sprinkler.allocate_user,#{queryForm.allocateUser})
AND t_sprinkler.is_new = #{queryForm.isNew}
AND INSTR(t_sprinkler.history,#{queryForm.history})
AND t_sprinkler.disabled_flag = #{queryForm.disabledFlag}
ORDER BY t_sprinkler.create_time DESC
ORDER BY
CASE WHEN LEFT(t_sprinkler.allocate_position, 2) = 'LK' THEN 7 WHEN LEFT(t_sprinkler.allocate_position, 1) = 'K' THEN 1 WHEN LEFT(t_sprinkler.allocate_position, 1) = 'C' THEN 2 WHEN LEFT(t_sprinkler.allocate_position, 1) = 'M' THEN 3 WHEN LEFT(t_sprinkler.allocate_position, 1) = 'Y' THEN 4 WHEN LEFT(t_sprinkler.allocate_position, 1) = 'O' THEN 5 WHEN LEFT(t_sprinkler.allocate_position, 1) = 'B' THEN 6 WHEN LEFT(t_sprinkler.allocate_position, 1) = 'R' THEN 8 ELSE 0 -- 显式处理未匹配情况 END, CAST(REGEXP_REPLACE(t_sprinkler.allocate_position, '[^0-9]', '') AS UNSIGNED) ${sortItem.isAsc ? 'ASC' : 'DESC'}
CASE WHEN t_sprinkler.sprinkler_serial REGEXP '^\\w{6}-\\d{2}$' THEN 0 ELSE 1 END ${sortItem.isAsc ? 'ASC' : 'DESC'}, SUBSTRING(t_sprinkler.sprinkler_serial, 1, 6) ${sortItem.isAsc ? 'ASC' : 'DESC'}, CAST(SUBSTRING(t_sprinkler.sprinkler_serial, 8, 2) AS UNSIGNED) ${sortItem.isAsc ? 'ASC' : 'DESC'}
`${sortItem.column}` ${sortItem.isAsc ? 'ASC' : 'DESC'}

